import{_ as t,o as a,c as n,ak as o}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Bounded parallel work and handoffs","description":"Updated October 23, 2026. The live board owns task status and history; GDD v2 owns scope. Card count is not school completion. This guide does not authorize automatic delegati","frontmatter":{"title":"Bounded parallel work and handoffs","description":"Updated October 23, 2026. The live board owns task status and history; GDD v2 owns scope. Card count is not school completion. This guide does not authorize automatic delegati","source":"docs/planning/agentic-parallel-execution-plan.md","category":"Delivery & team","sourceUpdated":"2026-10-23T16:51:22+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/planning/agentic-parallel-execution-plan.md","filePath":"content/docs/planning/agentic-parallel-execution-plan.md"}'),r={name:"content/docs/planning/agentic-parallel-execution-plan.md"};function i(d,e,s,c,l,p){return a(),n("div",null,[...e[0]||(e[0]=[o('<div><h1 id="bounded-parallel-work-and-handoffs">Bounded parallel work and handoffs<a class="header-anchor" href="#bounded-parallel-work-and-handoffs" aria-label="Link to this section">​</a></h1><p>Updated October 23, 2026. The <a href="https://owenlim225.github.io/Chainy-Docs/board/">live board</a> owns task status and history; <a href="/Chainy-Docs/content/docs/game-design.html">GDD v2</a> owns scope. Card count is not school completion. This guide does not authorize automatic delegation or overlapping source edits.</p><table><thead><tr><th>Owner</th><th>Responsibility</th><th>Handoff</th></tr></thead><tbody><tr><td>Sherwin</td><td>Design, priorities, community arrangements and readiness decisions</td><td>Approved v2 quest/economy rules and scope gates</td></tr><tr><td>Christian</td><td>Game code, SQLite, Android builds, integration and technical tests</td><td>Stable interfaces, verified builds and evidence</td></tr><tr><td>Luis</td><td>Production art and source/license notes</td><td>Reusable low-poly assets and import information</td></tr><tr><td>Sean</td><td>All authored project documents, copy, instruments and manuscript</td><td>Approved instructions and evidence records</td></tr><tr><td>Miguel</td><td>Player-facing UI</td><td>Prefabs/screens wired to Christian&#39;s interfaces; no gameplay or SQL ownership</td></tr></tbody></table><p>First prove W01–W04 with safe local saving, then B01–B03/demo B07 using the same lantern record. Art, copy and UI may proceed independently only after their required decisions/interfaces are stable. Christian controls shared scene/code integration. A helper gets one bounded card and returns its artifact, checks and gaps to its human owner; it does not decide scope or mark work accepted without evidence.</p><p>AI training is conditional stretch. Standalone Wordle/BlockMatch, full-world expansions and teacher services are later work, never prerequisites for the core integration card. Preserve completed historical cards and individual updates; create a distinct follow-up when an accepted artifact needs new verification.</p><p>Protect October 31–November 6 integration/device tests, November 7–9 regression/beta rehearsal, <strong>November 10 Cryptita Plays community beta</strong>, November 11–13 findings/fixes, November 14–16 manuscript and November 17–20 rehearsal. <strong>Pre-final remains November 21.</strong> Internal targets depend on measured capacity. Confirm school acceptance of community evidence separately.</p></div>',1)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
